      mainRecord.url = url;
      mainRecord.failed = true;
      mainRecord.localizedFailDescription = 'net::ERR_NAME_NOT_RESOLVED';
      const error = GatherRunner.getPageLoadError(url, [mainRecord]);
      assert.equal(error.message, 'DNS_FAILURE');
